dashboard.definition:
{
	"dataSources": {
		"ds_NnJc8xvB": {
			"type": "ds.search",
			"options": {
				"query": "index=linux_os sourcetype=system_metrics earliest=-5m\n| stats avg(cpu_usage) AS \"Average CPU %\" avg(ram_usage) AS \"Average RAM %\"",
				"queryParameters": {
					"earliest": "-24h@h",
					"latest": "now",
					"sampleRatio": 1
				}
			},
			"name": "verage CPU _ RAM _ Last 5 Minutes - Table search"
		}
	},
	"visualizations": {
		"viz_p1SLyxlQ": {
			"type": "splunk.table",
			"options": {
				"count": 20,
				"dataOverlayMode": "none",
				"drilldown": "none",
				"showRowNumbers": false,
				"showInternalFields": false
			},
			"dataSources": {
				"primary": "ds_NnJc8xvB"
			},
			"title": "verage CPU & RAM — Last 5 Minutes"
		}
	},
	"applicationProperties": {
		"hideEdit": false,
		"hideExport": false
	},
	"inputs": {
		"input_global_trp": {
			"type": "input.timerange",
			"options": {
				"token": "global_time",
				"defaultValue": "-24h@h,now"
			},
			"title": "Global Time Range"
		}
	},
	"layout": {
		"options": {},
		"globalInputs": [
			"input_global_trp"
		],
		"tabs": {
			"items": [
				{
					"layoutId": "layout_1",
					"label": "New tab"
				}
			]
		},
		"layoutDefinitions": {
			"layout_1": {
				"type": "grid",
				"structure": [
					{
						"item": "viz_p1SLyxlQ",
						"type": "block",
						"position": {
							"x": 0,
							"y": 0,
							"w": 1440,
							"h": 250
						}
					}
				],
				"options": {
					"width": 1440,
					"height": 960
				}
			}
		}
	},
	"title": "UF System Performance",
	"description": "",
	"defaults": {
		"dataSources": {
			"ds.search": {
				"options": {
					"queryParameters": {
						"latest": "$global_time.latest$",
						"earliest": "$global_time.earliest$"
					}
				}
			},
			"ds.spl2": {
				"options": {
					"queryParameters": {
						"latest": "$global_time.latest$",
						"earliest": "$global_time.earliest$"
					}
				}
			}
		},
		"visualizations": {
			"global": {
				"showProgressBar": true
			}
		}
	}
}
